fun reminderVisualTranslation(text:String,language:String):String? {
    val index=reminderVisualKeys.indexOf(text)
    return if(index<0)null else (reminderVisualRows[language] ?: reminderVisualRows.getValue("en")).split('|')[index]
}
fun reminderVisualText(text:String,language:String,value:Any)= (reminderVisualTranslation(text,language) ?: text).replace("{0}",value.toString())
